# validation.R -- Checks of the model on Lin, Lin, & Yeh (2023), Exps. 1, 3-4
#
# Reproduces every number in the manuscript's Step 6b and Supplemental
# Material S2 and S5 (Tables S1 and S4) that does not come from generate_figures.R. Run with the package installed. The script reads
# its input files from, and writes its CSV output to, the working directory,
# so copy this folder somewhere writable first, e.g.
#   file.copy(system.file("extdata", "lin2023_validation",
#                         package = "phonActivR"), ".", recursive = TRUE)
# and then, inside the copied folder:
#   Rscript validation.R            (about 40-60 minutes)
#
# Input files (in this folder), computed from the trial-level data of
# Lin et al. (2023), correct trials only (the selection used for the bundled
# lin2023_english, which the item file reproduces to rounding):
#   lin2023_item_curves.csv     mean x-coordinate (101 normalized steps) per
#                               group x item x condition, with trial counts
#   lin2023_subject_curves.csv  the same per group x participant x condition
#   lin2023_subject_rt.csv      mean response time (ms) per participant
#   lin2023_subject_curves_chinese.csv, lin2023_subject_rt_chinese.csv
#                               the same for Experiment 1 (Mandarin listening;
#                               one control per item serves both competitor
#                               types; CV effect from the 12 CV targets, C
#                               effect from the 12 C targets)
# Conditions: CV, CV Control, Onset (= C), Onset Control.
# Effect = control minus competitor x-coordinate (attraction to competitor).
# All data are de-identified means; no trial-level or demographic data.
#
# Settings shared with the manuscript: delta grid 0-30 in steps of 5,
# latency (lag) search 0-50 steps, joint CV + C fit as in fit_components(),
# asymmetry fit as in goodness_of_fit(), Gaussian reference as in
# shape_baseline().
#
# Sections
#  A. Held-out items: 200 random 21/21 item splits per group.
#  B. Participant bootstrap: 1,000 resamples per group; selected delta by
#     the asymmetry fit and by the joint fit, and the group difference.
#  C. Model variants on the full data (gate x residual_input).
#  D. Recovery under misspecification (data generated by a different model).
#  E. Response times, to express steps in milliseconds; between-participant
#     SD of the asymmetry, for power_guidance().
#  F. Sensitivity of the joint fit to the C input weight (c_weight).
#  G. Sensitivity to the control input (ctrl_scaling).
#  H. Mandarin listening (Experiment 1): participant bootstrap of the joint-fit
#     delta under both gate readings (shared and separate C scale), the C/CV
#     peak ratio, and the sensitivity of the selected delta to the input
#     settings (Application 2, Table 7; Supplemental Material, Table S4).
#  I. English versus Mandarin within the same 41 participants: paired
#     participant bootstrap of the relative C effect and of the joint-fit delta.
# Resampling is one-way: section A resamples items with participants fixed,
# section B participants with items fixed. A crossed (participant x item)
# bootstrap would need participant x item curves, which are not shipped.
# Additional variants in A-C: c_weight (weight of a C match relative to a
# CV match) chosen on the training items, and c_weight = 0.8.

suppressPackageStartupMessages(library(phonActivR))
DELTAS <- seq(0, 30, 5); LAGS <- 0:50
IC <- read.csv("lin2023_item_curves.csv", check.names = FALSE)
SC <- read.csv("lin2023_subject_curves.csv", check.names = FALSE)
RT <- read.csv("lin2023_subject_rt.csv")
xcols <- paste0("X_", 1:101)
stim <- example_stimuli()
quiet <- function(expr) suppressWarnings(suppressMessages(expr))

# Model versions used below
VARIANTS <- list(
  delay_rho0    = list(gate = "delay",    residual_input = 0),
  delay_rho1    = list(gate = "delay",    residual_input = 1),
  truncate_rho0 = list(gate = "truncate", residual_input = 0),
  truncate_rho1 = list(gate = "truncate", residual_input = 1))
SIMS <- lapply(VARIANTS, function(v)
  quiet(run_simulation(stim, delta_values = DELTAS, gate = v$gate,
                       residual_input = v$residual_input, verbose = FALSE)))
for (rho in c(.25, .5, .75)) {
  SIMS[[paste0("delay_rho", rho)]] <- quiet(run_simulation(
    stim, delta_values = DELTAS, residual_input = rho, verbose = FALSE))
}
CWS <- c(0.5, 0.6, 0.7, 0.8, 0.9, 1)
for (cw in CWS[-1]) {
  SIMS[[paste0("delay_cw", cw)]] <- quiet(run_simulation(
    stim, delta_values = DELTAS, c_weight = cw, verbose = FALSE))
  SIMS[[paste0("truncate_cw", cw)]] <- quiet(run_simulation(
    stim, delta_values = DELTAS, c_weight = cw, gate = "truncate", verbose = FALSE))
}
SIMS$delay_cw0.5 <- SIMS$delay_rho0; SIMS$truncate_cw0.5 <- SIMS$truncate_rho0

# Trial-weighted effect curves from rows of the item or subject table
eff <- function(tab, w = rep(1, nrow(tab))) {
  m <- function(k) { s <- tab$condition == k
    colSums(as.matrix(tab[s, xcols]) * tab$n_trials[s] * w[s]) / sum(tab$n_trials[s] * w[s]) }
  cv <- m("CV Control") - m("CV"); c <- m("Onset Control") - m("Onset")
  data.frame(time = 1:101, cv_effect = cv, c_effect = c, asymmetry = cv - c)
}
# A simulation restricted to a subset of items (item-level model curves)
sub_sim <- function(sim, items) {
  for (d in names(sim$results)) {
    L <- sim$item_results[[d]]$large_matrix[items, , drop = FALSE]
    S <- sim$item_results[[d]]$small_matrix[items, , drop = FALSE]
    sim$results[[d]]$large_effect <- colMeans(L)
    sim$results[[d]]$small_effect <- colMeans(S)
    sim$results[[d]]$asymmetry    <- colMeans(L) - colMeans(S)
  }
  sim
}
r2 <- function(y, yh) 1 - sum((y - yh)^2) / sum((y - mean(y))^2)
shift <- function(x, L) c(rep(0, L), x)[1:101]
predict_joint <- function(sim, row) {       # fitted CV and C curves
  res <- sim$results[[as.character(row$delta)]]
  list(cv = row$scale * shift(res$large_effect, row$lag),
       c  = row$scale_c * shift(res$small_effect, row$lag))
}
bump_pred <- function(y) {                  # Gaussian reference (shape_baseline)
  b <- shape_baseline(data.frame(time = 1:101, y = y), column = "y")
  b$scale * dnorm(1:101, b$center, b$width)
}
pick <- function(f) f[which.min(f$aic), ]

# ---- A. Held-out items ------------------------------------------------------
rowsA <- list(); withr::local_seed(20260930)
for (g in unique(IC$group)) { tab <- IC[IC$group == g, ]
  for (s in 1:200) {
    tr <- sort(sample(1:42, 21)); te <- setdiff(1:42, tr)
    etr <- eff(tab[tab$item %in% tr, ]); ete <- eff(tab[tab$item %in% te, ])
    fits <- lapply(c("delay_rho0", "delay_rho0.25", "delay_rho0.5",
                     "delay_rho0.75", "delay_rho1"), function(v) {
      f <- quiet(fit_components(sub_sim(SIMS[[v]], tr), etr, lag = LAGS, verbose = FALSE))
      cbind(variant = v, pick(f)) })
    fits <- do.call(rbind, fits)
    fitsw <- do.call(rbind, lapply(paste0("delay_cw", CWS), function(v) {
      f <- quiet(fit_components(sub_sim(SIMS[[v]], tr), etr, lag = LAGS, verbose = FALSE))
      cbind(variant = v, pick(f)) }))
    sel <- list(default = fits[fits$variant == "delay_rho0", ],
                residual_selected = fits[which.min(fits$aic), ],
                residual_1 = fits[fits$variant == "delay_rho1", ],
                c_weight_selected = fitsw[which.min(fitsw$aic), ],
                c_weight_0.8 = fitsw[fitsw$variant == "delay_cw0.8", ])
    for (nm in names(sel)) { p <- sel[[nm]]
      pr <- predict_joint(sub_sim(SIMS[[p$variant]], te), p)
      rowsA[[length(rowsA) + 1]] <- data.frame(group = g, split = s, model = nm,
        residual_input = SIMS[[p$variant]]$params$residual_input,
        c_weight = SIMS[[p$variant]]$params$c_weight, delta = p$delta,
        r2 = r2(c(ete$cv_effect, ete$c_effect), c(pr$cv, pr$c)),
        r2_cv = r2(ete$cv_effect, pr$cv), r2_c = r2(ete$c_effect, pr$c)) }
    pcv <- bump_pred(etr$cv_effect); pc <- bump_pred(etr$c_effect)
    rowsA[[length(rowsA) + 1]] <- data.frame(group = g, split = s, model = "gaussian_bumps",
      residual_input = NA, c_weight = NA, delta = NA, r2 = r2(c(ete$cv_effect, ete$c_effect), c(pcv, pc)),
      r2_cv = r2(ete$cv_effect, pcv), r2_c = r2(ete$c_effect, pc))
    rowsA[[length(rowsA) + 1]] <- data.frame(group = g, split = s, model = "training_curve",
      residual_input = NA, c_weight = NA, delta = NA,
      r2 = r2(c(ete$cv_effect, ete$c_effect), c(etr$cv_effect, etr$c_effect)),
      r2_cv = r2(ete$cv_effect, etr$cv_effect), r2_c = r2(ete$c_effect, etr$c_effect))
  } }
A <- do.call(rbind, rowsA); write.csv(A, "A_heldout_items.csv", row.names = FALSE)

# ---- B. Participant bootstrap -------------------------------------------------
rowsB <- list(); withr::local_seed(4242)
for (g in unique(SC$group)) { tab <- SC[SC$group == g, ]; subs <- unique(tab$subject)
  for (b in 0:1000) {
    w <- if (b == 0) rep(1, nrow(tab)) else {
      k <- table(factor(sample(subs, replace = TRUE), subs)); as.numeric(k[as.character(tab$subject)]) }
    em <- eff(tab, w)
    for (v in c("delay_rho0", "delay_rho1", "truncate_rho0", "delay_cw0.8", "truncate_cw0.8")) {
      fa <- quiet(goodness_of_fit(SIMS[[v]], em, lag = LAGS, verbose = FALSE))
      fj <- quiet(fit_components(SIMS[[v]], em, lag = LAGS, verbose = FALSE))
      fs <- quiet(fit_components(SIMS[[v]], em, lag = LAGS, shared_scale = FALSE,
                                 verbose = FALSE))
      rowsB[[length(rowsB) + 1]] <- data.frame(group = g, boot = b, variant = v,
        delta_asymmetry = pick(fa)$delta, delta_joint = pick(fj)$delta,
        delta_sepscale = pick(fs)$delta)
    } } }
B <- do.call(rbind, rowsB); write.csv(B, "B_bootstrap_delta.csv", row.names = FALSE)

# ---- C. Model variants on the full data ----------------------------------------
rowsC <- list()
for (g in unique(IC$group)) { em <- eff(IC[IC$group == g, ])
  for (v in c("delay_rho0", "delay_rho1", "truncate_rho0", "truncate_rho1",
              "delay_cw0.8", "truncate_cw0.8")) {
    fa <- quiet(goodness_of_fit(SIMS[[v]], em, lag = LAGS, verbose = FALSE))
    fj <- quiet(fit_components(SIMS[[v]], em, lag = LAGS, verbose = FALSE))
    fs <- quiet(fit_components(SIMS[[v]], em, lag = LAGS, shared_scale = FALSE, verbose = FALSE))
    rowsC[[length(rowsC) + 1]] <- data.frame(group = g, variant = v,
      asym_delta = pick(fa)$delta, asym_r2 = pick(fa)$r2,
      joint_delta = pick(fj)$delta, joint_r2 = pick(fj)$r2, joint_r2_cv = pick(fj)$r2_cv,
      joint_r2_c = pick(fj)$r2_c, best_r2_c_any_delta = max(fj$r2_c),
      sepscale_best_r2_c = max(fs$r2_c))
  } }
C <- do.call(rbind, rowsC); write.csv(C, "C_model_variants.csv", row.names = FALSE)

# ---- D. Recovery under misspecification -------------------------------------------
sim0 <- SIMS$delay_rho0; rowsD <- list()
gens <- list(same_model = list(), residual_input_1 = list(residual_input = 1),
             seg_steps_14 = list(seg_steps = 14), seg_steps_8 = list(seg_steps = 8),
             c_weight_0.8 = list(c_weight = 0.8))
for (nz in c(0.015, 0.18)) for (gn in names(gens)) for (td in c(0, 10)) for (m in c("components", "asymmetry")) {
  r <- quiet(parameter_recovery(sim0, true_delta = td, noise_sd = nz,
                                n_replications = 100, method = m, lag = 0:50,
                                generate_with = gens[[gn]], verbose = FALSE))
  rowsD[[length(rowsD) + 1]] <- data.frame(noise_sd = nz, generated_by = gn, true_delta = td, method = m,
    recovery = r$recovery_rate,
    selected = paste(names(r$selection_table), r$selection_table, sep = ":", collapse = " "))
}
D <- do.call(rbind, rowsD); write.csv(D, "D_misspecification.csv", row.names = FALSE)

# ---- F. Sensitivity to the C input weight -------------------------------------
rowsF <- list()
for (g in unique(IC$group)) { em <- eff(IC[IC$group == g, ])
  for (cw in CWS) for (gt in c("delay", "truncate")) {
    sm <- SIMS[[paste0(gt, "_cw", cw)]]
    fj <- quiet(fit_components(sm, em, lag = LAGS, verbose = FALSE))
    fs <- quiet(fit_components(sm, em, lag = LAGS, shared_scale = FALSE, verbose = FALSE))
    rowsF[[length(rowsF) + 1]] <- data.frame(group = g, gate = gt, c_weight = cw,
      joint_delta = pick(fj)$delta, joint_r2 = pick(fj)$r2, r2_cv = pick(fj)$r2_cv,
      r2_c = pick(fj)$r2_c, sep_scale_delta = pick(fs)$delta, sep_scale_r2_c = pick(fs)$r2_c)
  } }
Fv <- do.call(rbind, rowsF); write.csv(Fv, "F_c_weight_sensitivity.csv", row.names = FALSE)

# ---- G. Sensitivity to the control input -----------------------------------------
# By default a control's overlap is scaled by ctrl_scaling = 0.15, which keeps
# its activation near zero. A CV control shares the target's vowel, so larger
# values ask how much a stronger (vowel-sharing) control changes the fit.
rowsG <- list()
for (cs in c(0.15, 0.3, 0.5, 1)) {
  sm <- quiet(run_simulation(stim, delta_values = DELTAS, ctrl_scaling = cs,
                             verbose = FALSE))
  for (g in unique(IC$group)) { em <- eff(IC[IC$group == g, ])
    fa <- quiet(goodness_of_fit(sm, em, lag = LAGS, verbose = FALSE))
    fj <- quiet(fit_components(sm, em, lag = LAGS, verbose = FALSE))
    rowsG[[length(rowsG) + 1]] <- data.frame(group = g, ctrl_scaling = cs,
      asym_delta = pick(fa)$delta, asym_r2 = pick(fa)$r2,
      joint_delta = pick(fj)$delta, joint_r2 = pick(fj)$r2,
      r2_cv = pick(fj)$r2_cv, r2_c = pick(fj)$r2_c)
  } }
G <- do.call(rbind, rowsG); write.csv(G, "G_ctrl_scaling.csv", row.names = FALSE)

# ---- H. Mandarin listening (Experiment 1) ------------------------------------------
SCZ <- read.csv("lin2023_subject_curves_chinese.csv", check.names = FALSE)
stim_zh <- example_stimuli_zh(); sm_zh <- mandarin_similarity()
SIMZ <- list(delay = quiet(run_simulation(stim_zh, delta_values = DELTAS, similarity_matrix = sm_zh, verbose = FALSE)),
             truncate = quiet(run_simulation(stim_zh, delta_values = DELTAS, gate = "truncate",
                                             similarity_matrix = sm_zh, verbose = FALSE)))
subs_zh <- unique(SCZ$subject); rowsH <- list(); withr::local_seed(2401)
for (b in 0:1000) {
  w <- if (b == 0) rep(1, nrow(SCZ)) else {
    k <- table(factor(sample(subs_zh, replace = TRUE), subs_zh)); as.numeric(k[as.character(SCZ$subject)]) }
  em <- eff(SCZ, w)
  for (v in names(SIMZ)) {
    fj <- quiet(fit_components(SIMZ[[v]], em, lag = LAGS, verbose = FALSE))
    fs <- quiet(fit_components(SIMZ[[v]], em, lag = LAGS, shared_scale = FALSE, verbose = FALSE))
    rowsH[[length(rowsH) + 1]] <- data.frame(boot = b, gate = v, delta_joint = pick(fj)$delta,
      delta_sepscale = pick(fs)$delta,
      r2 = pick(fj)$r2, r2_c = pick(fj)$r2_c, c_cv_ratio = max(em$c_effect) / max(em$cv_effect)) } }
H <- do.call(rbind, rowsH); write.csv(H, "H_mandarin_bootstrap.csv", row.names = FALSE)
# Sensitivity of the Mandarin selection to the input settings (full data)
emz <- eff(SCZ); rowsH2 <- list()
zh_variants <- list(default = list(), c_weight_0.8 = list(c_weight = 0.8), c_weight_0.2 = list(c_weight = 0.2),
                    c_weight_0.1 = list(c_weight = 0.1), residual_input_1 = list(residual_input = 1),
                    seg_steps_8 = list(seg_steps = 8), seg_steps_14 = list(seg_steps = 14))
for (gt in c("delay", "truncate")) for (vn in names(zh_variants)) {
  sm <- quiet(do.call(run_simulation, c(list(stim_zh, delta_values = DELTAS, gate = gt,
                                            similarity_matrix = sm_zh, verbose = FALSE), zh_variants[[vn]])))
  fj <- quiet(fit_components(sm, emz, lag = LAGS, verbose = FALSE))
  fs <- quiet(fit_components(sm, emz, lag = LAGS, shared_scale = FALSE, verbose = FALSE))
  fa <- quiet(goodness_of_fit(sm, emz, lag = LAGS, verbose = FALSE))
  rowsH2[[length(rowsH2) + 1]] <- data.frame(gate = gt, variant = vn,
    joint_delta = pick(fj)$delta, joint_daic_delta0 = round(fj$aic[fj$delta == 0] - min(fj$aic), 1),
    sepscale_delta = pick(fs)$delta, sepscale_daic_delta0 = round(fs$aic[fs$delta == 0] - min(fs$aic), 1),
    asym_delta = pick(fa)$delta) }
# Control scored on its vowel/rime (small_ctrl_type = "CV") with the default
# and a stronger control input: the Mandarin control shares the target's vowel.
for (gt in c("delay", "truncate")) for (cs in c(0.15, 0.5)) {
  sm <- quiet(run_simulation(stim_zh, delta_values = DELTAS, gate = gt, similarity_matrix = sm_zh,
                             small_ctrl_type = "CV", ctrl_scaling = cs, verbose = FALSE))
  fj <- quiet(fit_components(sm, emz, lag = LAGS, verbose = FALSE))
  fs <- quiet(fit_components(sm, emz, lag = LAGS, shared_scale = FALSE, verbose = FALSE))
  fa <- quiet(goodness_of_fit(sm, emz, lag = LAGS, verbose = FALSE))
  rowsH2[[length(rowsH2) + 1]] <- data.frame(gate = gt, variant = paste0("ctrl_CV_scaling_", cs),
    joint_delta = pick(fj)$delta, joint_daic_delta0 = round(fj$aic[fj$delta == 0] - min(fj$aic), 1),
    sepscale_delta = pick(fs)$delta, sepscale_daic_delta0 = round(fs$aic[fs$delta == 0] - min(fs$aic), 1),
    asym_delta = pick(fa)$delta) }
H2 <- do.call(rbind, rowsH2); write.csv(H2, "H2_mandarin_variants.csv", row.names = FALSE)
# Signed C effect averaged over the window in which the CV effect exceeds half
# its maximum (a statistic that, unlike the peak, can be zero or negative).
win <- which(emz$cv_effect >= max(emz$cv_effect) / 2)
cwin <- function(em) mean(em$c_effect[win])
cw_boot <- withr::with_seed(2402, replicate(1000, {
  k <- table(factor(sample(subs_zh, replace = TRUE), subs_zh))
  cwin(eff(SCZ, as.numeric(k[as.character(SCZ$subject)]))) }))
cwin_full <- cwin(emz)

# ---- E (continued). Between-participant SD of the asymmetry at its peak ---------
sdrows <- list()
for (g in unique(SC$group)) { tab <- SC[SC$group == g, ]
  subs <- unique(tab$subject)
  per <- t(sapply(subs, function(u) eff(tab[tab$subject == u, ])$asymmetry))
  pk <- which.max(eff(tab)$asymmetry)
  sdrows[[g]] <- data.frame(group = g, peak_step = pk, between_sd = sd(per[, pk]))
}
SDs <- do.call(rbind, sdrows)

# ---- Report --------------------------------------------------------------------
q <- function(x) sprintf("%.2f [%.2f, %.2f]", median(x), quantile(x, .1), quantile(x, .9))
pct <- function(x, lv) round(100 * prop.table(table(factor(x, lv))), 1)
cat("\n########## A. Held-out items (test halves; median [10th, 90th pct]) ##########\n")
for (g in unique(A$group)) { cat("\n", g, "\n", sep = "")
  for (m in unique(A$model)) { z <- A[A$group == g & A$model == m, ]
    cat(sprintf("  %-18s joint %s | CV %s | C %s\n", m, q(z$r2), q(z$r2_cv), q(z$r2_c))) }
  z <- A[A$group == g & A$model == "residual_selected", ]
  cat("  residual_input chosen on training halves:"); print(table(z$residual_input))
  zw <- A[A$group == g & A$model == "c_weight_selected", ]
  cat("  c_weight chosen on training halves:"); print(table(zw$c_weight))
  cat("  splits in which c_weight_selected beats default on held-out C:",
      sum(zw$r2_c > A$r2_c[A$group == g & A$model == "default"]), "of 200\n")
  cat("  delta chosen (c_weight_selected):"); print(table(zw$delta))
  cat("  splits in which residual_selected beats default on held-out C:",
      sum(z$r2_c > A$r2_c[A$group == g & A$model == "default"]), "of 200\n")
  cat("  delta chosen (default model):"); print(table(A$delta[A$group == g & A$model == "default"]))
  cat("  delta chosen (residual_selected):"); print(table(z$delta)) }

cat("\n########## B. Participant bootstrap (1,000 resamples; % of resamples) ##########\n")
for (g in unique(B$group)) for (v in unique(B$variant)) {
  z <- B[B$group == g & B$variant == v, ]; zb <- z[z$boot > 0, ]
  cat(sprintf("\n%s | %s | full data: asymmetry %d, joint %d\n", g, v,
              z$delta_asymmetry[z$boot == 0], z$delta_joint[z$boot == 0]))
  cat("  asymmetry fit:"); print(pct(zb$delta_asymmetry, DELTAS))
  cat("  joint fit:    "); print(pct(zb$delta_joint, DELTAS))
  cat(sprintf("  joint fit, separate C scale (full data: %d):",
              z$delta_sepscale[z$boot == 0])); print(pct(zb$delta_sepscale, DELTAS)) }
cat("\nGroup difference, joint fit (bilinguals minus monolinguals; resamples paired by index,\n")
cat("groups resampled independently):\n")
for (v in unique(B$variant)) {
  bi <- B[B$group == unique(B$group)[1] & B$variant == v & B$boot > 0, "delta_joint"]
  mo <- B[B$group == unique(B$group)[2] & B$variant == v & B$boot > 0, "delta_joint"]
  d <- bi - mo
  cat(sprintf("  %-14s P(diff > 0) = %.3f | P(diff = 0) = %.3f | P(diff < 0) = %.3f | 95%% interval [%g, %g]\n",
              v, mean(d > 0), mean(d == 0), mean(d < 0), quantile(d, .025), quantile(d, .975))) }
cat("Group difference, joint fit with separate C scale:\n")
for (v in unique(B$variant)) {
  bi <- B[B$group == unique(B$group)[1] & B$variant == v & B$boot > 0, "delta_sepscale"]
  mo <- B[B$group == unique(B$group)[2] & B$variant == v & B$boot > 0, "delta_sepscale"]
  d <- bi - mo
  cat(sprintf("  %-14s P(diff > 0) = %.3f | P(diff = 0) = %.3f | P(diff < 0) = %.3f | 95%% interval [%g, %g]\n",
              v, mean(d > 0), mean(d == 0), mean(d < 0), quantile(d, .025), quantile(d, .975))) }

cat("\n########## C. Model variants on the full data ##########\n"); print(C, row.names = FALSE)
cat("\n########## F. Sensitivity to the C input weight (joint fit) ##########\n"); print(Fv, row.names = FALSE, digits = 3)
cat("\n########## G. Sensitivity to the control input (ctrl_scaling) ##########\n"); print(G, row.names = FALSE, digits = 3)
cat("\n########## H. Mandarin listening (Experiment 1; 1,000 participant resamples) ##########\n")
for (v in names(SIMZ)) { z <- H[H$gate == v, ]; zb <- z[z$boot > 0, ]
  cat(sprintf("%s | full data: joint delta %d, joint R2 %.3f, C R2 %.3f\n", v, z$delta_joint[z$boot == 0], z$r2[z$boot == 0], z$r2_c[z$boot == 0]))
  cat("  joint fit:"); print(pct(zb$delta_joint, DELTAS))
  cat(sprintf("  delta >= 10 in %.1f%% of resamples (separate C scale: %.1f%%)\n",
              100 * mean(zb$delta_joint >= 10), 100 * mean(zb$delta_sepscale >= 10))) }
cat("Sensitivity of the Mandarin selection to the input settings (full data):\n"); print(H2, row.names = FALSE)
cat(sprintf("Signed mean C effect over the CV half-maximum window (steps %d-%d): %.4f; 95%% interval [%.4f, %.4f]; CV mean over the window %.3f\n",
            min(win), max(win), cwin_full, quantile(cw_boot, .025), quantile(cw_boot, .975), mean(emz$cv_effect[win])))
zb <- H[H$gate == "truncate" & H$boot > 0, ]
cat(sprintf("C/CV peak ratio: full data %.3f; 95%% interval [%.3f, %.3f]; P(ratio < .2) = %.3f\n",
            H$c_cv_ratio[H$gate == "truncate" & H$boot == 0], quantile(zb$c_cv_ratio, .025), quantile(zb$c_cv_ratio, .975), mean(zb$c_cv_ratio < .2)))
RTZ <- read.csv("lin2023_subject_rt_chinese.csv")
cat(sprintf("Mandarin listening: M = %.0f ms, SD = %.0f (n = %d); one step = %.1f ms\n", mean(RTZ$mean_rt_ms), sd(RTZ$mean_rt_ms), nrow(RTZ), mean(RTZ$mean_rt_ms) / 100))
cat("\n########## D. Recovery under misspecification (100 replications; noise SD before smoothing .015 or .18) ##########\n")
print(D, row.names = FALSE)
cat("\n########## E. Response times and between-participant SD ##########\n")
print(SDs, row.names = FALSE)
g_scale <- round(mean(quiet(fit_components(SIMS$delay_rho0, eff(IC[IC$group == unique(IC$group)[1], ]),
                                           verbose = FALSE))$scale), 2)
cat("power_guidance() with the bilinguals' SD, joint-fit scale", g_scale, ", n = 41:\n")
sim4 <- quiet(run_simulation(stim, delta_values = c(0, 10, 20, 30), verbose = FALSE))
invisible(power_guidance(sim4, n_participants = 41, empirical_sd = round(SDs$between_sd[1], 3),
                         scale = g_scale))
for (g in unique(RT$group)) { x <- RT$mean_rt_ms[RT$group == g]
  cat(sprintf("%s: M = %.0f ms, SD = %.0f (n = %d); one step = %.1f ms; 10 steps = %.0f ms\n",
              g, mean(x), sd(x), length(x), mean(x) / 100, mean(x) / 10)) }

# ---- I. English versus Mandarin within participants (paired bootstrap) -------------
# Experiments 1 and 3 of Lin et al. (2023) tested the same 41 participants, so
# each resample draws participants once and uses the same draw for both
# languages. Reported: the signed C effect relative to the CV effect over each
# language's CV half-maximum window (a ratio that can be zero or negative), its
# English-minus-Mandarin difference, and the joint-fit delta in each language.
SCZ_I <- read.csv("lin2023_subject_curves_chinese.csv", check.names = FALSE)
SCE_I <- SC[SC$group == "Chinese-English bilinguals", ]
stopifnot(setequal(unique(SCZ_I$subject), unique(SCE_I$subject)))
subs_I <- sort(unique(SCE_I$subject))
stim_zh_I <- example_stimuli_zh(); sm_zh_I <- mandarin_similarity()
SIM_E <- list(delay = quiet(run_simulation(stim, delta_values = DELTAS, verbose = FALSE)),
              truncate = quiet(run_simulation(stim, delta_values = DELTAS, gate = "truncate", verbose = FALSE)))
SIM_Z <- list(delay = quiet(run_simulation(stim_zh_I, delta_values = DELTAS, similarity_matrix = sm_zh_I, verbose = FALSE)),
              truncate = quiet(run_simulation(stim_zh_I, delta_values = DELTAS, gate = "truncate",
                                              similarity_matrix = sm_zh_I, verbose = FALSE)))
win_E <- which(eff(SCE_I)$cv_effect >= max(eff(SCE_I)$cv_effect) / 2)
win_Z <- which(eff(SCZ_I)$cv_effect >= max(eff(SCZ_I)$cv_effect) / 2)
rel_c <- function(em, win) mean(em$c_effect[win]) / mean(em$cv_effect[win])
rowsI <- list(); withr::local_seed(2403)
for (b in 0:1000) {
  k <- if (b == 0) table(factor(subs_I, subs_I)) else table(factor(sample(subs_I, replace = TRUE), subs_I))
  ee <- eff(SCE_I, as.numeric(k[as.character(SCE_I$subject)]))
  ez <- eff(SCZ_I, as.numeric(k[as.character(SCZ_I$subject)]))
  r <- data.frame(boot = b, rel_c_english = rel_c(ee, win_E), rel_c_mandarin = rel_c(ez, win_Z))
  for (g in c("delay", "truncate")) {
    r[[paste0("delta_english_", g)]]  <- pick(quiet(fit_components(SIM_E[[g]], ee, lag = LAGS, verbose = FALSE)))$delta
    r[[paste0("delta_mandarin_", g)]] <- pick(quiet(fit_components(SIM_Z[[g]], ez, lag = LAGS, verbose = FALSE)))$delta
  }
  rowsI[[length(rowsI) + 1]] <- r }
PI <- do.call(rbind, rowsI); write.csv(PI, "I_paired_language.csv", row.names = FALSE)
cat("\n########## I. English versus Mandarin, same 41 participants (paired bootstrap, 1,000 resamples) ##########\n")
pb <- PI[PI$boot > 0, ]; full <- PI[PI$boot == 0, ]
qi <- function(x) sprintf("[%.3f, %.3f]", quantile(x, .025), quantile(x, .975))
cat(sprintf("Signed C effect relative to CV (window means): English %.3f %s; Mandarin %.3f %s\n",
            full$rel_c_english, qi(pb$rel_c_english), full$rel_c_mandarin, qi(pb$rel_c_mandarin)))
dI <- pb$rel_c_english - pb$rel_c_mandarin
cat(sprintf("English minus Mandarin: %.3f %s; P(difference > 0) = %.3f\n",
            full$rel_c_english - full$rel_c_mandarin, qi(dI), mean(dI > 0)))
for (g in c("delay", "truncate")) {
  de <- pb[[paste0("delta_english_", g)]]; dz <- pb[[paste0("delta_mandarin_", g)]]
  cat(sprintf("%s: P(delta Mandarin > delta English) = %.3f; P(equal) = %.3f; P(Mandarin >= 10 and English <= 5) = %.3f\n",
              g, mean(dz > de), mean(dz == de), mean(dz >= 10 & de <= 5))) }
